] as $sql)$pdo->exec($sql);
$checks=0;function ncheck(bool $ok,string $message):void{global $checks;$checks++;if(!$ok)throw new RuntimeException($message);}
function seedEvent(PDO $pdo,int $run,int $student,int $billing,string $key,string $status='Pending',int $attempts=0,string $updated='2000-01-01 00:00:00'):void{$pdo->prepare('INSERT INTO billing_run_assignments(run_id,student_id,billing_id,notification_state) VALUES(?,?,?,?)')->execute([$run,$student,$billing,$status]);$pdo->prepare('INSERT INTO billing_notification_outbox(run_id,student_id,billing_id,event_key,academic_year,semester,new_assessment_amount,term_remaining_balance,delivery_status,attempt_count,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute([$run,$student,$billing,$key,'2099-2100','1st',125,875,$status,$attempts,$updated]);}
