$dispatcher=new ManagedBillingNotificationDispatcher($pdo,2,0,1);
seedEvent($pdo,1,1,11,'managed-run:1:student:1');$before=(float)$pdo->query('SELECT remaining_balance FROM billing WHERE billing_id=11')->fetchColumn();$result=$dispatcher->dispatchDue(1,1);
ncheck($result['sent']===1,'pending event is delivered');ncheck((int)$pdo->query('SELECT COUNT(*) FROM payment_notifications WHERE recipient_user_id=101')->fetchColumn()===1,'correct student user receives one notification');ncheck($pdo->query("SELECT delivery_status FROM billing_notification_outbox WHERE run_id=1")->fetchColumn()==='Sent','outbox records durable delivery');ncheck($pdo->query("SELECT notification_state FROM billing_run_assignments WHERE run_id=1")->fetchColumn()==='Sent','assignment mirrors durable notification creation');ncheck((float)$pdo->query('SELECT remaining_balance FROM billing WHERE billing_id=11')->fetchColumn()===$before,'dispatch does not alter billing balance');
$dispatcher->dispatchDue(1,1);ncheck((int)$pdo->query('SELECT COUNT(*) FROM payment_notifications WHERE recipient_user_id=101')->fetchColumn()===1,'retry does not duplicate a sent event');
seedEvent($pdo,2,2,12,'managed-run:2:student:2');$pdo->prepare("INSERT INTO payment_notifications(recipient_user_id,event_key,title,body,target_url,read_at) VALUES(?,?,?,?,?,'2026-01-01 00:00:00')")->execute([102,'managed-run:2:student:2','Existing','Existing body','/existing']);$dispatcher->dispatchDue(1,2);ncheck((int)$pdo->query("SELECT COUNT(*) FROM payment_notifications WHERE event_key='managed-run:2:student:2'")->fetchColumn()===1,'database uniqueness makes replay idempotent');ncheck($pdo->query("SELECT read_at FROM payment_notifications WHERE event_key='managed-run:2:student:2'")->fetchColumn()==='2026-01-01 00:00:00','existing read state is preserved');
seedEvent($pdo,3,3,13,'managed-run:3:student:3');$dispatcher->dispatchDue(1,3);ncheck($pdo->query('SELECT delivery_status FROM billing_notification_outbox WHERE run_id=3')->fetchColumn()==='PendingAccountLink','missing account remains recoverable');ncheck($pdo->query('SELECT last_error FROM billing_notification_outbox WHERE run_id=3')->fetchColumn()==='RECIPIENT_ACCOUNT_NOT_LINKED','missing account stores safe classification');
seedEvent($pdo,4,4,14,'managed-run:4:student:4','Processing');$dispatcher->dispatchDue(1,4);ncheck($pdo->query('SELECT delivery_status FROM billing_notification_outbox WHERE run_id=4')->fetchColumn()==='Sent','abandoned Processing claim recovers');
seedEvent($pdo,5,1,11,'managed-run:5:student:1');$pdo->exec("CREATE TRIGGER fail_notice BEFORE INSERT ON payment_notifications WHEN NEW.event_key='managed-run:5:student:1' BEGIN SELECT RAISE(ABORT,'injected'); END");$dispatcher->dispatchDue(1,5);ncheck($pdo->query('SELECT delivery_status FROM billing_notification_outbox WHERE run_id=5')->fetchColumn()==='Failed','storage failure remains diagnosable');$dispatcher->dispatchDue(1,5);$dispatcher->dispatchDue(1,5);ncheck((int)$pdo->query('SELECT attempt_count FROM billing_notification_outbox WHERE run_id=5')->fetchColumn()===2,'permanent failure stops at bounded attempts');ncheck((float)$pdo->query('SELECT remaining_balance FROM billing WHERE billing_id=11')->fetchColumn()===$before,'failed retries do not alter billing');
$source=(string)file_get_contents(__DIR__.'/../modules/payment/includes/ManagedBillingNotificationDispatcher.php');$schema=(string)file_get_contents(__DIR__.'/../modules/payment/database/migrations/managed-billing-migration.sql').(string)file_get_contents(__DIR__.'/../modules/payment/database/migrations/add_fee_billing_workflow.sql');$shared=(string)file_get_contents(__DIR__.'/../includes/notifications.php');
ncheck(str_contains($source,'FOR UPDATE')&&str_contains($schema,'uq_billing_notification_outbox_event')&&str_contains($schema,'uq_payment_notification_event'),'row locking and database uniqueness protect concurrent delivery');ncheck(str_contains($shared,'FROM payment_notifications WHERE recipient_user_id = ?')&&str_contains($shared,'read_at = COALESCE(read_at, NOW())'),'shared student UI reads Payment notifications and preserves read state');
$cli=(string)file_get_contents(__DIR__.'/../modules/payment/dispatch-managed-billing-notifications.php');ncheck(str_contains($cli,"PHP_SAPI!=='cli'")&&str_contains($cli,"'historical-before::'"),'recovery worker is CLI-only and historical recovery is explicitly scoped');
